"""Independent reference implementation using fractions.Fraction arithmetic."""
from fractions import Fraction as Fr

K_FIN, K_INF, K_QNAN, K_SNAN = 0, 1, 2, 3


def ref_solve(ebits, fbits, mode, pairs):
    bias = 2 ** (ebits - 1) - 1
    F = 2 ** fbits
    Eall = 2 ** ebits - 1
    width = 1 + ebits + fbits
    vmask = (1 << width) - 1
    fmask = F - 1
    top = 1 << (fbits - 1)
    emin = 1 - bias
    emax = Eall - 1 - bias
    two = Fr(2)

    def dec(h):
        v = int(h, 16) & vmask
        s = v >> (ebits + fbits)
        e = (v >> fbits) & Eall
        f = v & fmask
        if e == Eall:
            if f == 0:
                return ('inf', s, None)
            return ('nan', s, f)
        if e == 0:
            return ('num', s, Fr(f) * two ** (1 - bias - fbits))
        return ('num', s, Fr(F + f) * two ** (e - bias - fbits))

    def bits_of(sign, e, f):
        return (sign << (ebits + fbits)) | (e << fbits) | f

    invalid = sawnan = posinf = neginf = False
    prods = []
    for a_h, b_h in pairs:
        a, b = dec(a_h), dec(b_h)
        if a[0] == 'nan' or b[0] == 'nan':
            sawnan = True
            if (a[0] == 'nan' and not (a[2] & top)) or (b[0] == 'nan' and not (b[2] & top)):
                invalid = True
            continue
        if a[0] == 'inf' or b[0] == 'inf':
            other_zero = (a[0] == 'num' and a[2] == 0) or (b[0] == 'num' and b[2] == 0)
            if other_zero:
